import{_ as s,o as e,c as t,ag as n}from"./chunks/framework.VvOSaRrC.js";const u=JSON.parse('{"title":"PR Lifecycle Automation","description":"","frontmatter":{},"headers":[],"relativePath":"en/pr-lifecycle.md","filePath":"en/pr-lifecycle.md"}'),i={name:"en/pr-lifecycle.md"};function l(p,a,o,r,d,c){return e(),t("div",null,[...a[0]||(a[0]=[n(`<h1 id="pr-lifecycle-automation" tabindex="-1">PR Lifecycle Automation <a class="header-anchor" href="#pr-lifecycle-automation" aria-label="Permalink to &quot;PR Lifecycle Automation&quot;">​</a></h1><blockquote><p>Automated pull request management from creation to merge with CI monitoring and review resolution.</p></blockquote><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>PR Lifecycle Automation handles the complete pull request workflow:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Pre-PR Checks (build, test, lint)</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Create PR (gh pr create)</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>CI Monitoring Loop (max 10 min, 5 retry cycles)</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Review Resolution Loop (max 3 cycles)</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Merge &amp; Cleanup</span></span></code></pre></div><hr><h2 id="workflow-stages" tabindex="-1">Workflow Stages <a class="header-anchor" href="#workflow-stages" aria-label="Permalink to &quot;Workflow Stages&quot;">​</a></h2><h3 id="stage-1-pre-pr-checks" tabindex="-1">Stage 1: Pre-PR Checks <a class="header-anchor" href="#stage-1-pre-pr-checks" aria-label="Permalink to &quot;Stage 1: Pre-PR Checks&quot;">​</a></h3><p>Before creating a PR, the workflow verifies:</p><ul><li>No uncommitted changes</li><li>Build passes locally</li><li>Tests pass locally</li><li>Lint passes locally</li><li>Branch is pushed to remote</li></ul><h3 id="stage-2-create-pr" tabindex="-1">Stage 2: Create PR <a class="header-anchor" href="#stage-2-create-pr" aria-label="Permalink to &quot;Stage 2: Create PR&quot;">​</a></h3><p>Generates a structured PR with:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>## Summary</span></span>
<span class="line"><span>- What this PR does (1-3 bullet points)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Changes</span></span>
<span class="line"><span>- List of significant changes</span></span>
<span class="line"><span></span></span>
<span class="line"><span>## Test Plan</span></span>
<span class="line"><span>- [ ] Unit tests pass</span></span>
<span class="line"><span>- [ ] Integration tests pass</span></span>
<span class="line"><span>- [ ] Manual testing completed</span></span></code></pre></div><p>PR title follows conventional commits format: <code>feat(scope): description</code></p><h3 id="stage-3-ci-monitoring-loop" tabindex="-1">Stage 3: CI Monitoring Loop <a class="header-anchor" href="#stage-3-ci-monitoring-loop" aria-label="Permalink to &quot;Stage 3: CI Monitoring Loop&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌──────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│              CI Monitoring Loop                   │</span></span>
<span class="line"><span>│                                                   │</span></span>
<span class="line"><span>│  Check CI Status ──▶ All Passing? ──▶ Done       │</span></span>
<span class="line"><span>│       │                    │                      │</span></span>
<span class="line"><span>│       │               No (Failed)                 │</span></span>
<span class="line"><span>│       │                    │                      │</span></span>
<span class="line"><span>│       │         ┌─────────▼──────────┐            │</span></span>
<span class="line"><span>│       │         │ Diagnose Failure   │            │</span></span>
<span class="line"><span>│       │         │ Fix Issue          │            │</span></span>
<span class="line"><span>│       │         │ Push Fix           │            │</span></span>
<span class="line"><span>│       │         └─────────┬──────────┘            │</span></span>
<span class="line"><span>│       │                   │                       │</span></span>
<span class="line"><span>│       │            Retry &lt; 5?                     │</span></span>
<span class="line"><span>│       │           ├── Yes → Re-check              │</span></span>
<span class="line"><span>│       │           └── No  → STOP                  │</span></span>
<span class="line"><span>│       │                                           │</span></span>
<span class="line"><span>│       └── Pending? Wait 60s, re-check (max 10m)  │</span></span>
<span class="line"><span>└──────────────────────────────────────────────────┘</span></span></code></pre></div><p><strong>CI Failure Categories</strong>:</p><table tabindex="0"><thead><tr><th>Category</th><th>Auto-Fix</th><th>Example</th></tr></thead><tbody><tr><td>Lint error</td><td>Yes</td><td><code>npm run lint --fix</code></td></tr><tr><td>Type error</td><td>Fix types</td><td>Missing type annotation</td></tr><tr><td>Test failure</td><td>Fix code</td><td>Assertion mismatch</td></tr><tr><td>Build error</td><td>Fix build</td><td>Missing dependency</td></tr><tr><td>Flaky test</td><td>Re-run</td><td><code>gh run rerun &lt;id&gt;</code></td></tr></tbody></table><h3 id="stage-4-review-resolution-loop" tabindex="-1">Stage 4: Review Resolution Loop <a class="header-anchor" href="#stage-4-review-resolution-loop" aria-label="Permalink to &quot;Stage 4: Review Resolution Loop&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Read all review comments</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Categorize (bug/style/suggestion/question)</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Fix all issues in single commit</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Push and re-request review</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Repeat (max 3 cycles)</span></span></code></pre></div><p><strong>Comment Priority</strong>:</p><table tabindex="0"><thead><tr><th>Type</th><th>Priority</th><th>Action</th></tr></thead><tbody><tr><td>Bug/Logic error</td><td>Critical</td><td>Fix immediately</td></tr><tr><td>Style/Convention</td><td>Medium</td><td>Apply suggestion</td></tr><tr><td>Suggestion/Optional</td><td>Low</td><td>Evaluate and respond</td></tr><tr><td>Question</td><td>Low</td><td>Answer in comment</td></tr></tbody></table><h3 id="stage-5-merge-cleanup" tabindex="-1">Stage 5: Merge &amp; Cleanup <a class="header-anchor" href="#stage-5-merge-cleanup" aria-label="Permalink to &quot;Stage 5: Merge &amp; Cleanup&quot;">​</a></h3><ul><li>Verify all CI checks passing</li><li>Verify review approved</li><li>Squash merge and delete branch</li><li>Switch to main and pull</li></ul><hr><h2 id="timeout-protection" tabindex="-1">Timeout Protection <a class="header-anchor" href="#timeout-protection" aria-label="Permalink to &quot;Timeout Protection&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td>CI wait timeout</td><td>10 min</td><td>Max time to wait for CI completion</td></tr><tr><td>CI retry cycles</td><td>5</td><td>Max fix-and-recheck attempts</td></tr><tr><td>Polling interval</td><td>60s</td><td>Time between CI status checks</td></tr><tr><td>Review cycles</td><td>3</td><td>Max rounds of review resolution</td></tr></tbody></table><hr><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h2><h3 id="slash-command" tabindex="-1">Slash Command <a class="header-anchor" href="#slash-command" aria-label="Permalink to &quot;Slash Command&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Default PR lifecycle (squash merge to main)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/kroot:pr-lifecycle</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Custom base branch</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/kroot:pr-lifecycle</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --base</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> develop</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Draft PR</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/kroot:pr-lifecycle</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --draft</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Merge commit instead of squash</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/kroot:pr-lifecycle</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --merge</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Keep branch after merge</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">/kroot:pr-lifecycle</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --no-delete-branch</span></span></code></pre></div><h3 id="command-options" tabindex="-1">Command Options <a class="header-anchor" href="#command-options" aria-label="Permalink to &quot;Command Options&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Option</th><th>Description</th><th>Default</th></tr></thead><tbody><tr><td><code>--base &lt;branch&gt;</code></td><td>Base branch for PR</td><td>main</td></tr><tr><td><code>--squash</code></td><td>Squash merge</td><td>true</td></tr><tr><td><code>--merge</code></td><td>Merge commit</td><td>false</td></tr><tr><td><code>--no-delete-branch</code></td><td>Keep branch after merge</td><td>false</td></tr><tr><td><code>--draft</code></td><td>Create as draft PR</td><td>false</td></tr></tbody></table><h3 id="as-a-skill" tabindex="-1">As a Skill <a class="header-anchor" href="#as-a-skill" aria-label="Permalink to &quot;As a Skill&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Skill(&quot;kroot-workflow-pr-lifecycle&quot;)</span></span></code></pre></div><hr><h2 id="related-documentation" tabindex="-1">Related Documentation <a class="header-anchor" href="#related-documentation" aria-label="Permalink to &quot;Related Documentation&quot;">​</a></h2><ul><li><a href="./poc-first.html">POC-First Workflow</a> — Phase 5 uses this skill</li><li><a href="./task-format.html">Structured Task Format</a> — PR tasks use 5-field format</li><li><a href="./ralph-loop.html">Ralph Loop</a> — CI fix loop similar pattern</li><li><a href="./../ko/commands.html">Git Workflow</a> — Git conventions and branching</li></ul>`,38)])])}const m=s(i,[["render",l]]);export{u as __pageData,m as default};
